import net.minecraft.world.entity.animal.cow.Cow;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.Vec3;

/** Hostile Sauvojen's actual four shared arcs retain native electrical damage semantics. */
public final class HostileElectroChecks {
    private HostileElectroChecks(){}
    private static void require(boolean value,String why){if(!value)throw new IllegalStateException("Hostile Electro: "+why);}
    private static void near(double actual,double expected,String why){require(Math.abs(actual-expected)<.00001,why+" actual="+actual+" expected="+expected);}
    private static Object read(Object object,String name){for(Class<?> type=object.getClass();type!=null;type=type.getSuperclass())try{var field=type.getDeclaredField(name);field.setAccessible(true);return field.get(object);}catch(NoSuchFieldException ignored){}catch(IllegalAccessException error){throw new IllegalStateException(error);}throw new IllegalStateException("Missing native fixture field "+name);}
    private static void equipment(LivingEntity target){try{var method=LivingEntity.class.getDeclaredMethod("detectEquipmentUpdates");method.setAccessible(true);method.invoke(target);}catch(ReflectiveOperationException error){throw new IllegalStateException(error);}}
    private static final EquipmentSlot[] SLOTS={EquipmentSlot.FEET,EquipmentSlot.LEGS,EquipmentSlot.CHEST,EquipmentSlot.HEAD};
    private static final String[] PARTS={"boots","leggings","chestplate","helmet"};
    private static final Vec3 MOTION=new Vec3(.11,.07,-.13);
    private static final class Fixture implements AutoCloseable {
        final ElementalGrimoireChecks.Fixture base;final GameController game;final LbcWands wands;
        final Set<LbcWands.ElectroTrace> traces;final List<LbcWands.ElectroTrace> originalTraces,batch;
        final Collection<LbcStonekivi.Work> queue;final List<LbcStonekivi.Work> originalQueue;
        final Map<BlockPos,MapManager.BlockSnapshot> frame=new LinkedHashMap<>();final List<Entity> created=new ArrayList<>();
        final net.minecraft.world.scores.PlayerTeam oldTeam,team;final LivingEntity emitter;final LbcSpellSource.Source source;
        final ItemStack[] techno=new ItemStack[4];DamageSource actualHit;
        final Map<net.minecraft.stats.Stat<?>,Integer> stats=new LinkedHashMap<>();final Map<java.lang.reflect.Field,Object> profile=new LinkedHashMap<>();
        final Map<net.minecraft.advancements.AdvancementHolder,Set<String>> advancements=new LinkedHashMap<>();final SauvojenMeditationChecks.Attribution attribution;
        @SuppressWarnings("unchecked") Fixture(GameController game){this.game=game;base=new ElementalGrimoireChecks.Fixture(game,true);base.retain=true;wands=game.items().wands();attribution=new SauvojenMeditationChecks.Attribution(game,List.of(base.owner));
            for(var id:net.minecraft.core.registries.BuiltInRegistries.CUSTOM_STAT){var stat=net.minecraft.stats.Stats.CUSTOM.get(id);stats.put(stat,base.owner.getStats().getValue(stat));}
            for(var adv:game.server().getAdvancements().getAllAdvancements()){var done=new HashSet<String>();base.owner.getAdvancements().getOrStartProgress(adv).getCompletedCriteria().forEach(done::add);advancements.put(adv,done);}
            try{for(var field:game.players().get(base.owner.getUUID()).getClass().getFields())if(!java.lang.reflect.Modifier.isStatic(field.getModifiers())){var v=field.get(game.players().get(base.owner.getUUID()));profile.put(field,v instanceof int[] a?a.clone():v instanceof Set<?> set?new HashSet<>(set):v);}}catch(IllegalAccessException error){throw new IllegalStateException(error);}
            traces=(Set<LbcWands.ElectroTrace>)read(wands,"electroTraces");originalTraces=new ArrayList<>(traces);batch=(List<LbcWands.ElectroTrace>)read(wands,"electroBatch");require(batch.isEmpty(),"not inside an existing electrical batch");queue=(Collection<LbcStonekivi.Work>)read(game.items().stonekivi(),"work");originalQueue=new ArrayList<>(queue);traces.clear();base.initialize();
            for(var at:BlockPos.betweenClosed(base.owner.blockPosition().offset(-8,-3,-8),base.owner.blockPosition().offset(8,5,8)))frame.put(at.immutable(),game.maps().snapshot(base.owner.level(),at));
            var board=game.server().getScoreboard();oldTeam=base.owner.getTeam();require(board.getPlayerTeam("codex_helectro")==null,"exclusive fixture team");team=board.addPlayerTeam("codex_helectro");team.setAllowFriendlyFire(false);board.addPlayerToTeam(base.owner.getScoreboardName(),team);
            var ghost=EntityTypes.GHAST.create(base.owner.level(),EntitySpawnReason.COMMAND);require(ghost!=null,"native raw ghast emitter");emitter=ghost;emitter.setPos(base.owner.position().add(-5,0,5));emitter.entityTags().addAll(List.of("sauvojen_tuntija","rcdenyalways"));emitter.setNoGravity(true);require(base.owner.level().addFreshEntity(emitter),"published native hostile emitter");created.add(emitter);
            source=game.items().spellSources().hostile(emitter,base.owner,Set.of("sauvojen_tuntija","rcdenyalways","friendly_tuntija","strict_map_object"));game.items().spellSources().bind(emitter,source);
            for(int i=0;i<4;i++){var loot=game.lbc().rollTable(base.owner.level(),base.owner.position(),base.owner,"lbc:neko_set_techno/"+PARTS[i]);require(loot.size()==1&&LbcFartus.data(loot.getFirst()).getIntOr("techno",0)==1,"actual native original Techno slot payload "+PARTS[i]);techno[i]=loot.getFirst();}
        }
        Cow cow(){var victim=new Cow(EntityTypes.COW,base.owner.level());victim.setPos(base.owner.position().add(4,0,1));victim.setNoAi(true);victim.setNoGravity(true);victim.getAttribute(Attributes.MAX_HEALTH).setBaseValue(500);victim.setHealth(200);victim.setDeltaMovement(MOTION);victim.setInvulnerableTime(0);victim.damageCooldownTime=100;require(base.owner.level().addFreshEntity(victim),"published resident native cow victim");created.add(victim);game.server().getScoreboard().addPlayerToTeam(victim.getScoreboardName(),team);require(base.owner.isAlliedTo(victim),"native no-friendly-fire team ally");
            // In 26.3 Entity.invulnerableTime is temporary immunity, separate from hurt cooldown.
            require(!victim.isInvulnerable()&&victim.damageCooldownTime==100,"vulnerable native target with actual100tick damage cooldown");
            require(victim.getType().builtInRegistryHolder().is(net.minecraft.tags.TagKey.create(Registries.ENTITY_TYPE,net.minecraft.resources.Identifier.parse("minecraft:mobs"))),"actual native mobs selector contains cow");return victim;}
        void discard(Entity entity){if(entity.getTeam()==team)game.server().getScoreboard().removePlayerFromTeam(entity.getScoreboardName(),team);game.items().entityUnloaded(entity);if(entity instanceof LivingEntity living)game.items().indirectKills().clear(living);entity.discard();created.remove(entity);}
        void launch(Cow victim){
            var from=base.owner.position().add(4,.5,-1);var to=from.add(0,0,3.6);var box=victim.getBoundingBox();
            require(base.owner.level().getEntities((Entity)null,new net.minecraft.world.phys.AABB(from,to).inflate(1),e->e==victim).contains(victim),"published victim appears in native segment broadphase");
            var entry=box.clip(from,to);var exit=box.clip(to,from);require(entry.isPresent()&&exit.isPresent(),"native ray intersects victim in both directions");
            int first=(int)Math.ceil(from.distanceTo(entry.get())/.2-1e-6),last=(int)Math.floor(from.distanceTo(exit.get())/.2+1e-6);
            require(last-first+1==5,"native cow geometry admits exactly five sampled contacts per arc: first="+first+" last="+last);
            require(traces.isEmpty(),"only this native four-arc volley");wands.hostileSauvojenElectro(base.owner,base.owner.position().add(4,.5,-1),new Vec3(0,0,1),source);require(traces.size()==4&&traces.stream().allMatch(t->t.hostileSauvojen&&t.sourcePolicy==source&&t.owner==base.owner&&t.lifetime==20&&t.cause==source.cause()),"four actual hostile shared traces preserve authority/cause/lifetime");wands.tick();require(traces.size()==4&&traces.stream().allMatch(t->t.age==1),"actual shared native trace engine advanced four rays");require(traces.stream().allMatch(t->t.position.distanceToSqr(to)<1e-10),"four actual rays cross complete resident victim segment without shield or mechanism clipping");traces.clear();}
        void registry(){var type=base.owner.registryAccess().lookupOrThrow(Registries.DAMAGE_TYPE).getOrThrow(LbcDamage.ELECTRIC);var damage=new DamageSource(type,emitter);require(damage.is(LbcDamage.ELECTRIC)&&LbcDamage.isElectric(damage),"existing ELECTRIC registry and shared electric tag");require(damage.is(net.minecraft.tags.DamageTypeTags.NO_KNOCKBACK),"existing electric native no-knockback tag");require(damage.is(net.minecraft.tags.DamageTypeTags.BYPASSES_COOLDOWN),"existing ELECTRIC native cooldown bypass tag");require(!LbcDamage.isArrowDamage(damage)&&!damage.is(net.minecraft.tags.DamageTypeTags.IS_PROJECTILE),"existing base electricity is nonarrow and nonprojectile");require(type.value().scaling()==DamageScaling.NEVER&&type.value().exhaustion()==0,"existing electric never-scales and exhaustion0 source definition");}
        void contact(){var victim=cow();try{try(var scope=game.items().spellSources().scope(source)){
                require(Boolean.TRUE.equals(game.items().spellSources().target(base.owner,victim))&&wands.projectileTarget(base.owner,victim),"native hostile policy admits actual same-team victim");
                var probe=game.items().indirectKills().captureDamage(new DamageSource(base.owner.registryAccess().lookupOrThrow(Registries.DAMAGE_TYPE).getOrThrow(LbcDamage.ELECTRIC),base.owner),source.cause());
                require(!victim.isInvulnerableTo(base.owner.level(),probe)&&game.items().allowDamage(victim,probe),"actual captured electrical source passes native immunity and shared damage admission");
            }launch(victim);near(victim.getHealth(),190,"four real arcs each make five native0.5 contacts despite100tick hurt cooldown");require(victim.getDeltaMovement().equals(MOTION),"actual electric hits preserve native velocity");actualHit=victim.getLastDamageSource();require(actualHit!=null&&actualHit.is(LbcDamage.ELECTRIC)&&LbcDamage.isElectric(actualHit),"actual shared trace-hit DamageSource uses existing electric identity");require(!LbcDamage.isArrowDamage(actualHit)&&!actualHit.is(net.minecraft.tags.DamageTypeTags.IS_PROJECTILE),"actual contact remains nonarrow/nonprojectile");require(LbcIndirectKills.isWildCaptured(actualHit)&&actualHit.getEntity()==base.owner&&victim.getLastHurtByPlayer()==base.owner,"actual same-team hit retains WILD causal player and native hurt attribution");try(var scope=game.items().spellSources().scope(source)){require(Boolean.TRUE.equals(game.items().spellSources().target(base.owner,base.owner)),"hostile authority admits its causal wearer as a target");require(Boolean.FALSE.equals(game.items().spellSources().target(base.owner,emitter)),"actual emitter excluded by source identity");}}finally{discard(victim);}}
        void roles(){for(String tag:List.of("spectator","strict_map_object","magic_academy","rcdenyalways","friendly_tuntija","sauvojen_tuntija")){var victim=cow();victim.entityTags().add(tag);try{launch(victim);near(victim.getHealth(),200,"actual native ray excludes role "+tag);require(victim.getDeltaMovement().equals(MOTION),"excluded role preserves velocity "+tag);}finally{discard(victim);}}}
        void immunity(){for(int count:new int[]{4,3}){var victim=cow();try{for(int i=0;i<4;i++)victim.setItemSlot(SLOTS[i],i<count?techno[i].copy():ItemStack.EMPTY);equipment(victim);launch(victim);if(count==4)near(victim.getHealth(),200,"four actual equipped original Techno flags immunize native hostile contact");else require(victim.getHealth()<200,"actual partial Techno positive control remains electrically vulnerable");require(victim.getDeltaMovement().equals(MOTION),"both admitted/rejected electric hits preserve velocity");}finally{discard(victim);}}}
        void metal(){require(actualHit!=null,"use the real captured native trace-hit source");var iron=new Item[]{Items.IRON_BOOTS,Items.IRON_LEGGINGS,Items.IRON_CHESTPLATE,Items.IRON_HELMET};for(int count=0;count<=4;count++){for(int i=0;i<4;i++)base.owner.setItemSlot(SLOTS[i],i<count?new ItemStack(iron[i]):ItemStack.EMPTY);near(LbcDamage.incomingDamage(base.owner,actualHit,.5f),.5*(1+.25*count),"actual captured hostile source enters shared player raw-metal modifier count"+count);}for(int i=0;i<4;i++)base.owner.setItemSlot(SLOTS[i],ItemStack.EMPTY);base.owner.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.COPPER_HELMET));near(LbcDamage.incomingDamage(base.owner,actualHit,.5f),.625,"ordinary copper also contributes one raw electrical25percent layer");}
        public void close(){boolean exact=true;try{traces.clear();for(var entity:List.copyOf(created))discard(entity);for(var e:frame.entrySet()){exact&=game.maps().snapshot(base.owner.level(),e.getKey()).equals(e.getValue());game.maps().restoreSnapshot(base.owner.level(),e.getKey(),e.getValue());}for(var task:List.copyOf(queue))if(!originalQueue.contains(task))task.cancel();queue.clear();queue.addAll(originalQueue);var board=game.server().getScoreboard();board.removePlayerTeam(team);if(oldTeam!=null)board.addPlayerToTeam(base.owner.getScoreboardName(),oldTeam);}finally{traces.clear();traces.addAll(originalTraces);batch.clear();base.close();attribution.close();stats.forEach((stat,value)->base.owner.getStats().setValue(base.owner,stat,value));advancements.forEach((adv,done)->{for(var criterion:adv.value().criteria().keySet())if(done.contains(criterion))base.owner.getAdvancements().award(adv,criterion);else base.owner.getAdvancements().revoke(adv,criterion);});try{for(var entry:profile.entrySet())entry.getKey().set(game.players().get(base.owner.getUUID()),entry.getValue());}catch(IllegalAccessException error){throw new IllegalStateException(error);}}require(exact,"resident air frame and exact block entity snapshots preserved");require(new ArrayList<>(traces).equals(originalTraces)&&new ArrayList<>(queue).equals(originalQueue),"original electrical traces and shared work queue restored exactly");}
    }
    public static void run(GameController game){try(var f=new Fixture(game)){f.registry();f.contact();f.roles();f.immunity();f.metal();}SkyWars2.LOGGER.info("[check] PASS hostile-electro (four native hostile traces: electric contact/cooldown/velocity/attribution, allied targets, roles, actual Techno immunity and shared raw player metal modifier; no player hurt assertion)");}
}
